-- Phases B-D: durable attachments, profiles/staff and specialist channel content.
alter table public.channels drop constraint if exists channels_type_check;
alter table public.channels add constraint channels_type_check check (type in ('TEXT','VOICE','LIST','DOCS','CALENDAR','FORUM'));

create table if not exists public.message_attachments (
 id uuid primary key default gen_random_uuid(), message_id uuid references public.messages(id) on delete cascade,
 channel_id uuid not null references public.channels(id) on delete cascade, storage_path text not null unique,
 file_name text not null check(char_length(file_name) between 1 and 180), content_type text not null, byte_size bigint not null check(byte_size between 1 and 10485760), created_at timestamptz not null default now());
create table if not exists public.list_items (
 id uuid primary key default gen_random_uuid(), channel_id uuid not null references public.channels(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 240), note text not null default '', done boolean not null default false, assignee uuid references public.profiles(id) on delete set null, position integer not null default 0, created_by uuid not null references public.profiles(id), updated_at timestamptz not null default now());
create table if not exists public.documents (
 id uuid primary key default gen_random_uuid(), channel_id uuid not null references public.channels(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 160), body text not null default '', created_by uuid not null references public.profiles(id), updated_at timestamptz not null default now());
create table if not exists public.calendar_events (
 id uuid primary key default gen_random_uuid(), channel_id uuid not null references public.channels(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 160), description text not null default '', starts_at timestamptz not null, ends_at timestamptz, created_by uuid not null references public.profiles(id), updated_at timestamptz not null default now(), check(ends_at is null or ends_at>=starts_at));
create table if not exists public.event_rsvps (event_id uuid references public.calendar_events(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, status text not null check(status in ('going','maybe','declined')), primary key(event_id,user_id));
create table if not exists public.forum_topics (
 id uuid primary key default gen_random_uuid(), channel_id uuid not null references public.channels(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 180), body text not null check(char_length(trim(body)) between 1 and 8000), author uuid not null references public.profiles(id), pinned boolean not null default false, locked boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.forum_replies (id uuid primary key default gen_random_uuid(), topic_id uuid not null references public.forum_topics(id) on delete cascade, body text not null check(char_length(trim(body)) between 1 and 8000), author uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.voice_states (channel_id uuid not null references public.channels(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, muted boolean not null default false, deafened boolean not null default false, updated_at timestamptz not null default now(), primary key(channel_id,user_id));
create table if not exists public.platform_admins (user_id uuid primary key references public.profiles(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.profile_badges (user_id uuid not null references public.profiles(id) on delete cascade, badge text not null check(badge in ('staff','early-supporter','verified')), assigned_at timestamptz not null default now(), primary key(user_id,badge));
alter table public.profiles add column if not exists avatar_url text not null default '';
alter table public.profiles add column if not exists banner_url text not null default '';

alter table public.message_attachments enable row level security; alter table public.list_items enable row level security; alter table public.documents enable row level security; alter table public.calendar_events enable row level security; alter table public.event_rsvps enable row level security; alter table public.forum_topics enable row level security; alter table public.forum_replies enable row level security; alter table public.voice_states enable row level security; alter table public.platform_admins enable row level security; alter table public.profile_badges enable row level security;
revoke all on public.message_attachments,public.list_items,public.documents,public.calendar_events,public.event_rsvps,public.forum_topics,public.forum_replies,public.voice_states,public.platform_admins,public.profile_badges from anon,authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('attachments','attachments',false,10485760,null) on conflict(id) do update set public=false,file_size_limit=10485760;
drop policy if exists "attachment reads follow channel access" on storage.objects;
create policy "attachment reads follow channel access" on storage.objects for select to authenticated using (bucket_id='attachments' and public.app_access((storage.foldername(name))[2]::uuid));
drop policy if exists "attachment uploads follow channel permission" on storage.objects;
create policy "attachment uploads follow channel permission" on storage.objects for insert to authenticated with check (bucket_id='attachments' and public.app_access((storage.foldername(name))[2]::uuid,true) and (storage.foldername(name))[1]='channels');

create or replace function public.app_is_platform_admin(p_user uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from platform_admins where user_id=p_user)$$;
create or replace function public.app_feature_api(p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare me uuid:=auth.uid(); ch uuid:=nullif(p_payload->>'channel','')::uuid; item uuid:=nullif(p_payload->>'id','')::uuid; topic uuid:=nullif(p_payload->>'topic','')::uuid; srv uuid; result jsonb; pos int;
begin
 if me is null then raise exception 'Please sign in'; end if;
 if ch is not null and not app_access(ch, p_action like '%/write' or p_action like '%/create' or p_action like '%/save' or p_action like '%/delete' or p_action like '%/toggle') then raise exception 'You do not have access to this channel'; end if;
 if p_action='attachment/create' then
  if not app_access(ch,true) then raise exception 'You cannot attach files here'; end if;
  insert into message_attachments(message_id,channel_id,storage_path,file_name,content_type,byte_size) values(nullif(p_payload->>'message','')::uuid,ch,p_payload->>'path',left(p_payload->>'name',180),left(p_payload->>'content_type',120),(p_payload->>'size')::bigint) returning id into item; return jsonb_build_object('id',item);
 end if;
 if p_action='attachment/bind' then update message_attachments set message_id=nullif(p_payload->>'message','')::uuid where id=item and channel_id=ch and message_id is null and exists(select 1 from messages where id=nullif(p_payload->>'message','')::uuid and sender=me and channel_id=ch); if not found then raise exception 'Attachment could not be added to that message'; end if; return '{}'::jsonb; end if;
 if p_action='list/create' then select coalesce(max(position)+1,0) into pos from list_items where channel_id=ch; insert into list_items(channel_id,title,note,assignee,position,created_by) values(ch,left(trim(p_payload->>'title'),240),left(coalesce(p_payload->>'note',''),2000),nullif(p_payload->>'assignee','')::uuid,pos,me) returning id into item; return jsonb_build_object('id',item); end if;
 if p_action='list/save' then update list_items set title=left(trim(p_payload->>'title'),240),note=left(coalesce(p_payload->>'note',''),2000),done=coalesce((p_payload->>'done')::boolean,done),assignee=nullif(p_payload->>'assignee','')::uuid,updated_at=now() where id=item and channel_id=ch and (created_by=me or app_has((select server_id from channels where id=ch),'manage_lists')); if not found then raise exception 'You cannot change this list item'; end if; return '{}'::jsonb; end if;
 if p_action='list/delete' then delete from list_items where id=item and channel_id=ch and (created_by=me or app_has((select server_id from channels where id=ch),'manage_lists')); if not found then raise exception 'You cannot delete this list item'; end if; return '{}'::jsonb; end if;
 if p_action='docs/create' then insert into documents(channel_id,title,body,created_by) values(ch,left(trim(p_payload->>'title'),160),left(coalesce(p_payload->>'body',''),30000),me) returning id into item; return jsonb_build_object('id',item); end if;
 if p_action='docs/save' then update documents set title=left(trim(p_payload->>'title'),160),body=left(coalesce(p_payload->>'body',''),30000),updated_at=now() where id=item and channel_id=ch and (created_by=me or app_has((select server_id from channels where id=ch),'manage_docs')); if not found then raise exception 'You cannot edit this document'; end if; return '{}'::jsonb; end if;
 if p_action='docs/delete' then delete from documents where id=item and channel_id=ch and (created_by=me or app_has((select server_id from channels where id=ch),'manage_docs')); if not found then raise exception 'You cannot delete this document'; end if; return '{}'::jsonb; end if;
 if p_action='calendar/create' then insert into calendar_events(channel_id,title,description,starts_at,ends_at,created_by) values(ch,left(trim(p_payload->>'title'),160),left(coalesce(p_payload->>'description',''),4000),(p_payload->>'starts_at')::timestamptz,nullif(p_payload->>'ends_at','')::timestamptz,me) returning id into item; return jsonb_build_object('id',item); end if;
 if p_action='calendar/save' then update calendar_events set title=left(trim(p_payload->>'title'),160),description=left(coalesce(p_payload->>'description',''),4000),starts_at=(p_payload->>'starts_at')::timestamptz,ends_at=nullif(p_payload->>'ends_at','')::timestamptz,updated_at=now() where id=item and channel_id=ch and (created_by=me or app_has((select server_id from channels where id=ch),'manage_events')); if not found then raise exception 'You cannot edit this event'; end if; return '{}'::jsonb; end if;
 if p_action='calendar/delete' then delete from calendar_events where id=item and channel_id=ch and (created_by=me or app_has((select server_id from channels where id=ch),'manage_events')); if not found then raise exception 'You cannot delete this event'; end if; return '{}'::jsonb; end if;
 if p_action='calendar/rsvp' then insert into event_rsvps(event_id,user_id,status) values(item,me,p_payload->>'status') on conflict(event_id,user_id) do update set status=excluded.status; return '{}'::jsonb; end if;
 if p_action='forum/create' then insert into forum_topics(channel_id,title,body,author) values(ch,left(trim(p_payload->>'title'),180),left(trim(p_payload->>'body'),8000),me) returning id into item; return jsonb_build_object('id',item); end if;
 if p_action='forum/reply' then if exists(select 1 from forum_topics where id=topic and locked) and not app_has((select server_id from channels where id=ch),'manage_topics') then raise exception 'This topic is locked'; end if; insert into forum_replies(topic_id,body,author) values(topic,left(trim(p_payload->>'body'),8000),me) returning id into item; update forum_topics set updated_at=now() where id=topic; return jsonb_build_object('id',item); end if;
 if p_action='forum/moderate' then update forum_topics set pinned=coalesce((p_payload->>'pinned')::boolean,pinned),locked=coalesce((p_payload->>'locked')::boolean,locked),updated_at=now() where id=item and channel_id=ch and app_has((select server_id from channels where id=ch),'manage_topics'); if not found then raise exception 'You cannot moderate this topic'; end if; return '{}'::jsonb; end if;
 if p_action='voice/join' then insert into voice_states(channel_id,user_id) values(ch,me) on conflict(channel_id,user_id) do update set updated_at=now(); return '{}'::jsonb; end if;
 if p_action='voice/leave' then delete from voice_states where channel_id=ch and user_id=me; return '{}'::jsonb; end if;
 if p_action='voice/state' then update voice_states set muted=coalesce((p_payload->>'muted')::boolean,muted),deafened=coalesce((p_payload->>'deafened')::boolean,deafened),updated_at=now() where channel_id=ch and user_id=me; return '{}'::jsonb; end if;
 if p_action='staff/badge' then if not app_is_platform_admin() then raise exception 'Platform staff only'; end if; insert into profile_badges(user_id,badge) values((p_payload->>'user')::uuid,p_payload->>'badge') on conflict do nothing; return '{}'::jsonb; end if;
 raise exception 'Unknown feature operation';
end $$;
create or replace function public.app_feature_state(p_channel uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare typ text; begin if not app_access(p_channel) then raise exception 'You do not have access to this channel'; end if; select type into typ from channels where id=p_channel; if typ='LIST' then return jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(i) order by i.position,i.updated_at) from list_items i where i.channel_id=p_channel),'[]')); end if; if typ='DOCS' then return jsonb_build_object('docs',coalesce((select jsonb_agg(to_jsonb(d) order by d.updated_at desc) from documents d where d.channel_id=p_channel),'[]')); end if; if typ='CALENDAR' then return jsonb_build_object('events',coalesce((select jsonb_agg(to_jsonb(e)||jsonb_build_object('rsvps',coalesce((select jsonb_agg(to_jsonb(r)) from event_rsvps r where r.event_id=e.id),'[]')) order by e.starts_at) from calendar_events e where e.channel_id=p_channel),'[]')); end if; if typ='FORUM' then return jsonb_build_object('topics',coalesce((select jsonb_agg(to_jsonb(t)||jsonb_build_object('reply_count',(select count(*) from forum_replies r where r.topic_id=t.id),'replies',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at) from forum_replies r where r.topic_id=t.id),'[]')) order by t.pinned desc,t.updated_at desc) from forum_topics t where t.channel_id=p_channel),'[]')); end if; if typ='VOICE' then return jsonb_build_object('participants',coalesce((select jsonb_agg(app_public_profile(v.user_id)||jsonb_build_object('muted',v.muted,'deafened',v.deafened)) from voice_states v where v.channel_id=p_channel and v.updated_at>now()-interval '2 minutes'),'[]')); end if; return '{}'::jsonb; end $$;
revoke all on function public.app_feature_api(text,jsonb),public.app_feature_state(uuid),public.app_is_platform_admin(uuid) from public,anon;
grant execute on function public.app_feature_api(text,jsonb),public.app_feature_state(uuid),public.app_is_platform_admin(uuid) to authenticated;
notify pgrst,'reload schema';
